package theme

// Caret is the input caret.
const Caret = "▏"

// Ellipsis is the kit's default ellipsis, for a cut made with no theme at hand.
const Ellipsis = "…"

// Marks are the status marks.
var Marks = []rune{'●', '○', '◆'}
